function l6Print(title,html,extraCss){const w=window.open('','_blank');if(!w)return alertMsg('پنجره‌ی چاپ باز نشد؛ اجازه‌ی پاپ‌آپ را بدهید.');
  w.document.write(`<html dir="rtl"><head><meta charset="utf-8"><title>${l6Esc(title)}</title><style>body{font-family:Vazirmatn,Tahoma,sans-serif;padding:18px;font-size:12px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #999;padding:4px;vertical-align:top}button,.acts,input[type=checkbox],details{display:none!important}.l6x{display:inline-flex;gap:4px;align-items:center}.l6xg{display:inline-grid;grid-template-columns:auto auto;border:1px solid #333}.l6xg i{font-style:normal;padding:0 3px;min-width:14px;font-size:10px}.l6xg i:nth-child(1),.l6xg i:nth-child(3){border-left:1px solid #333}.l6xg i:nth-child(1),.l6xg i:nth-child(2){border-bottom:1px solid #333}input{border:0;font:inherit;width:auto}${extraCss||''}</style></head><body><h2>${l6Esc(title)}</h2>${html}</body></html>`);w.document.close();setTimeout(()=>w.print(),350)}
