  b(`data-l6a="note" data-lid="${l6Esc(lid)}"`,'اضافه کردن یادداشت');b(`data-l2prt="${l6Esc(lid)}"`,'چاپ برگه‌ی سفارش');
  const s=mkSheet('l6MenuSh',`<h3>سفارش #${l2No(x.no)} — ${l6Esc(x.name)}</h3><div class="l6mbtn">${B.join('')}</div><div class="btns"><button class="btn ghost" type="button" id="l6MenuX">بستن</button></div>`);s.style.zIndex=62;s.hidden=false;
