const L6MC=[['row','ردیف'],['chk','فاکتور'],['day','تاریخ'],['done','تاریخ تکمیل'],['title','عنوان'],['doc','پزشک'],['wo','دستور کار'],['pat','نام بیمار'],['box','شماره جعبه'],['wt','نوع کار'],['q','تعداد/دندان'],['p','قیمت واحد'],['mat','هزینه متریال'],['mi','اطلاعات متریال'],['deb','بدهکاری'],['dpct','درصد تخفیف'],['cred','بستانکاری'],['bal','مانده'],['det','جزئیات'],['note','توضیحات']];
